#!/system/bin/sh
# {{MODULE_NAME}} v{{VERSION_NAME}} ({{VERSION_CODE}}) — install-time customization.
# Sourced by Magisk/KernelSU/APatch install_module after it has extracted the zip to $MODPATH.
# Generated by DFTB {{APP_VERSION}}. POSIX sh only; no bashisms.
#
# Variables provided by the installer: MODPATH, ARCH, API, ui_print, abort, set_perm, set_perm_recursive.

# Let the installer extract the module tree normally (module.prop, system/, *.sh).
SKIPUNZIP=0

ui_print "- {{MODULE_NAME}} v{{VERSION_NAME}} ({{VERSION_CODE}})"
ui_print "- {{MIN_MAGISK_NOTE}}"
ui_print "- {{MIN_KERNELSU_NOTE}}"
ui_print "- Bundled tools: {{TOOL_LIST}}"

# Only 64-bit userspace is supported; tools are built for arm64-v8a and x86_64 only.
case "$ARCH" in
  arm64|x64)
    ui_print "- Architecture: $ARCH"
    ;;
  *)
    abort "! Unsupported architecture '$ARCH'; this module requires arm64 or x86_64"
    ;;
esac

# Java's zip writer cannot set unix permission bits, so every extracted file is non-executable.
# Make the bundled CLI tools executable here — this is the canonical place to do it.
if [ -d "$MODPATH/system/bin" ]; then
  ui_print "- Setting permissions on system/bin"
  set_perm_recursive "$MODPATH/system/bin" 0 0 0755 0755
fi

# Lifecycle scripts must be executable by the boot stages that run them.
for s in post-fs-data.sh service.sh uninstall.sh; do
  [ -f "$MODPATH/$s" ] && set_perm "$MODPATH/$s" 0 0 0755
done

# Create DFTB's root-owned state tree up front so first boot has somewhere to journal to.
ui_print "- Preparing {{DATA_ROOT}}"
mkdir -p "{{JOURNAL_DIR}}"
set_perm_recursive "{{DATA_ROOT}}" 0 0 0700 0700 2>/dev/null

ui_print "- Done. Reboot to activate the companion module."
